text:
{
  "title": "سياسة الخصوصية وشروط الاستخدام لشركة الأفق الرقمي المحدودة",
  "planted": [
    {
      "slot": "p1",
      "text": "يمكنكم الاطلاع على التفاصيل الكاملة المتعلقة بأغراض جمع البيانات، وطبيعة البيانات الشخصية التي يتم جمعها، وآليات معالجتها وتخزينها وإتلافها، بالإضافة إلى حقوق أصحاب البيانات وكيفية ممارستها، وذلك عبر زيارة صفحة الشروط والأحكام المتاحة على موقعنا الإلكتروني قبل الشروع في استخدام خدماتنا."
    },
    {
      "slot": "p2",
      "text": "لا يتم الاعتماد على المصالح المشروعة كأساس لمعالجة البيانات الحساسة كالأصل العرقي أو العقائد الدينية أو السياسية أو السجلات الجنائية أو البيانات البيومترية والجينية والصحية، كما يُحظر تماماً استخدام البيانات الصحية في الأنشطة التسويقية، ويقتصر الوصول إليها حصراً على الفئات المخولة التي تتطلب مهامهم الوظيفية ذلك."
    },
    {
      "slot": "p3",
      "text": "تحرص الشركة على جمع القدر الملائم من البيانات الشخصية بما يتناسب مع طبيعة التعاملات والخدمات المقدمة دون إفراط."
    }
  ],
  "neutral": [
    "تخضع كافة المعاملات المالية ورسوم الاشتراكات للأسعار المعلنة في قائمة الأسعار الرسمية للشركة، ويتم استيفاء المدفوعات عبر وسائل الدفع المعتمدة لديها.",
    "تبدأ هذه الاتفاقية من تاريخ قبول المستخدم لشروطها وتظل سارية حتى يتم إنهاؤها من قبل أي من الطرفين وفقاً للإجراءات المحددة.",
    "لا تتحمل الشركة أي مسؤولية قانونية عن الأضرار غير المباشرة أو الخسائر التبعية الناتجة عن سوء استخدام الخدمات المقدمة.",
    "تخضع هذه الشروط والأحكام وتفسر وفقاً للأنظمة المعمول بها في المملكة العربية السعودية وتختص المحاكم المختصة بالفصل في أي نزاع ينشأ عنها.",
    "تعتبر حقوق الملكية الفكرية لجميع المحتويات والتصاميم والعلامات التجارية التابعة للشركة ملكاً خالصاً لها ولا يجوز استخدامها دون إذن خطي مسبق."
  ]
}
